import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
import { z } from "zod/v4";
import { challenges, type EvalOutcome, type MockState } from "./fixtures";
import { executeEval, IMAGE } from "./isolate";
import type { AgentToolUse, ProviderAdapter } from "../../server/lib/agent/provider";
import type { ResolvedToolDefinition } from "../../server/lib/agent/types";

const root = fileURLToPath(new URL("../../", import.meta.url));
const docs = `${root}docs/task-call-challenges`;
const LIMITS = { responses: 5, evals: 6, requestMs: 120_000, responseChars: 64_000 };
const MODELS = ["nugjp:codex:gpt-5.6-luna", "nug2:antigravity:gemini-3.7-flash"];
const hash = (text: string) => createHash("sha256").update(text).digest("hex");
const secrets = new Set<string>();
function safeError(error: unknown): string {
	let message = String(error);
	for (const secret of secrets) if (secret) message = message.split(secret).join("[REDACTED]");
	return message.replace(/Bearer\s+\S+/gi, "Bearer [REDACTED]").slice(0, 1800);
}

async function selfTest() {
	let passed = 0;
	for (const challenge of challenges) {
		let state = challenge.makeState();
		let value: unknown;
		for (const code of challenge.reference) {
			const result = await executeEval(state, code);
			if (!result.ok) throw new Error(`reference ${challenge.id}: ${JSON.stringify(result.error)}`);
			state = result.state; value = result.value;
		}
		const grade = challenge.grade(state, value);
		if (!grade.pass) throw new Error(`reference ${challenge.id}: ${grade.reasons.join("; ")}`);
		const bad = await executeEval(challenge.makeState(), challenge.negative);
		if (challenge.grade(bad.state, bad.value).pass) throw new Error(`negative ${challenge.id} was falsely accepted`);
		passed += 2;
		console.log(`self-test ${challenge.id}: reference PASS, negative rejected`);
	}
	const disallowed = await executeEval(challenges[0].makeState(), "await task.start();");
	if (!disallowed.interfaceViolation) throw new Error("await was not rejected");
	console.log(JSON.stringify({ selfTest: "PASS", fixtureChecks: passed, asyncRejection: true, image: IMAGE }));
}

const evalTool = {
	name: "Eval",
	description: "执行同步 TypeScript，操作 API.md 中的任务对象和模拟工具。只有通过此工具执行的操作才算完成；不支持 await/async/import。输入 code，返回实际执行结果或错误。",
	parameters: z.object({ code: z.string() }),
	rawJsonSchema: { type: "object", properties: { code: { type: "string", description: "同步 TypeScript 代码；可使用 return 返回结果" } }, required: ["code"], additionalProperties: false },
	execute: async () => ({ output: "Only the challenge harness may execute this tool.", isError: true }),
} as ResolvedToolDefinition;

async function makeAdapter(fullModel: string) {
	const { getNugProviderConfig } = await import("../../server/lib/settings");
	const { loadAllCachedNugModels, resolveNugModelMeta, getNugCachedModelHash } = await import("../../server/lib/nug-model-cache");
	loadAllCachedNugModels();
	const prefix = fullModel.split(":")[0];
	const config = getNugProviderConfig(prefix);
	if (!config) throw new Error(`Configured model route unavailable: ${prefix}`);
	secrets.add(config.apiKey);
	const meta = resolveNugModelMeta(config.id, prefix, fullModel);
	const routed = fullModel.slice(prefix.length + 1);
	if (meta.routedModel !== routed) throw new Error(`Refusing model substitution: ${fullModel} -> ${meta.routedModel}`);
	const url = config.baseUrl.trim().replace(/\/+$/, "").replace(/\/(?:api\/v1|api|v1)$/i, "");
	if (meta.channelType !== "codex" && meta.channelType !== "anthropic") throw new Error(`Unsupported test route: ${meta.channelType}`);
	const { BenchProvider } = await import("./client");
	const adapter = new BenchProvider({ baseUrl: url, apiKey: config.apiKey, model: meta.routedModel, protocol: meta.channelType, proxy: config.proxy, modelHash: getNugCachedModelHash(config.id) ?? "none" }) as unknown as ProviderAdapter;
	return { adapter, channelType: meta.channelType, model: fullModel };
}

async function makeCapture() {
	const { ApiRequestDumpCollector } = await import("../../server/lib/agent/request-dump");
	return new (class extends ApiRequestDumpCollector {
		requests: Array<Record<string, unknown>> = [];
		override setRequest(request: any) {
			const body = request.body ?? {};
			const effort = body.reasoning?.effort ?? body.output_config?.effort ?? body.reasoning_effort;
			const names = (body.tools ?? []).map((t: any) => t.name ?? t.function?.name ?? t.type);
			this.requests.push({ model: body.model, effort, tools: names, thinkingType: body.thinking?.type });
			if (effort !== "low") throw new Error(`LOW_EFFORT_NOT_SENT: ${String(effort)}`);
			if (names.length !== 1 || names[0] !== "Eval") throw new Error("UNEXPECTED_TOOL_EXPOSURE");
		}
		override setResponseMeta(_response: any) { /* Deliberately do not retain headers, bodies, or thinking. */ }
	})();
}

async function oneResponse(adapter: ProviderAdapter, params: any) {
	const controller = new AbortController();
	const timer = setTimeout(() => controller.abort(new Error("request deadline")), LIMITS.requestMs);
	const capture = await makeCapture();
	let text = "";
	let reasoningChars = 0;
	let accumulatedChars = 0;
	let messageId: string | undefined;
	let textOutputIndex: number | undefined;
	let stopReason: string | undefined;
	let usage: unknown;
	const completed = new Map<string, AgentToolUse>();
	const chunks = new Map<string, { name: string; input: string; outputIndex?: number; thoughtSignature?: string; thoughtSignatureSource?: string }>();
	const reasoning = new Map<string, any>();
	const redacted: any[] = [];
	try {
		for await (const event of adapter.chat({ ...params, signal: controller.signal, requestDump: capture, reasoningEffort: "low" })) {
			if (event.text) { text += event.text; accumulatedChars += event.text.length; }
			if (event.textOutputIndex !== undefined) textOutputIndex = event.textOutputIndex;
			if (event.messageId) messageId = event.messageId;
			if (event.stopReason) stopReason = event.stopReason;
			if (event.usage) usage = event.usage;
			if (event.invalidState) throw new Error(`UPSTREAM_INVALID_STATE: ${event.invalidState.message}`);
			if (event.reasoning || event.reasoningMetadata) {
				const key = String(event.reasoningOutputIndex ?? 0);
				const part = reasoning.get(key) ?? { text: "", outputIndex: event.reasoningOutputIndex };
				part.text += event.reasoning ?? "";
				if (event.reasoningMetadata) part.providerMetadata = { ...(part.providerMetadata ?? {}), ...event.reasoningMetadata };
				reasoningChars += event.reasoning?.length ?? 0;
				accumulatedChars += event.reasoning?.length ?? 0;
				reasoning.set(key, part);
			}
			if (event.redactedThinking) redacted.push(event.redactedThinking);
			for (const call of event.toolUses ?? []) completed.set(call.toolUseId, call);
			if (event.toolUseChunk) {
				const update = event.toolUseChunk;
				const part = chunks.get(update.toolUseId) ?? { name: "", input: "" };
				if (update.name) part.name = update.name;
				if (update.input) { part.input += update.input; accumulatedChars += update.input.length; }
				if (update.outputIndex !== undefined) part.outputIndex = update.outputIndex;
				if (update.thoughtSignature) part.thoughtSignature = update.thoughtSignature;
				if (update.thoughtSignatureSource) part.thoughtSignatureSource = update.thoughtSignatureSource;
				chunks.set(update.toolUseId, part);
			}
			if (accumulatedChars > LIMITS.responseChars) { controller.abort(); throw new Error("MODEL_RESPONSE_LIMIT"); }
		}
		for (const [id, chunk] of chunks) {
			if (completed.has(id)) continue;
			let input: Record<string, unknown>;
			try { input = JSON.parse(chunk.input); }
			catch { input = { malformedInput: chunk.input }; }
			completed.set(id, { toolUseId: id, name: chunk.name, input, outputIndex: chunk.outputIndex, thoughtSignature: chunk.thoughtSignature, thoughtSignatureSource: chunk.thoughtSignatureSource });
		}
		return { text, calls: [...completed.values()], reasoning: [...reasoning.values()], redacted, messageId, textOutputIndex, usage, stopReason, reasoningChars, wire: capture.requests };
	} finally { clearTimeout(timer); }
}

async function runEpisode(model: string, challengeId: string, api: string) {
	const challenge = challenges.find((c) => c.id === challengeId)!;
	const { adapter, channelType } = await makeAdapter(model);
	const prompt = await Bun.file(`${docs}/${challenge.file}`).text();
	const conversationId = `task-challenge-${crypto.randomUUID()}`;
	const history: unknown[] = [];
	adapter.injectSystemPrompt(history, api, model, "zh-CN");
	const tools = adapter.formatTools([evalTool]);
	let state = challenge.makeState();
	let pending: unknown[] = [];
	let lastValue: unknown;
	let evalCount = 0;
	let firstEvalPass = false;
	let finalText = "";
	let infrastructureError: string | undefined;
	let naturalStop = false;
	const turns: any[] = [];
	const started = Date.now();
	for (let turn = 0; turn < LIMITS.responses; turn++) {
		let response: Awaited<ReturnType<typeof oneResponse>>;
		try {
			response = await oneResponse(adapter, { conversationId, stickySessionKey: conversationId, content: turn === 0 ? prompt : "", model, cwd: "/work", history, tools, toolResults: pending });
		} catch (error) {
			infrastructureError = safeError(error);
			break;
		}
		const record: any = { turn: turn + 1, text: response.text, calls: response.calls.map((c) => ({ name: c.name, input: c.input })), usage: response.usage, stopReason: response.stopReason, reasoningChars: response.reasoningChars, wire: response.wire, evals: [] };
		turns.push(record);
		if (turn === 0) adapter.pushUserTurn(history, prompt, model, []);
		else if (pending.length) adapter.pushUserTurn(history, "", model, pending);
		adapter.pushAssistantTurn(history, response.text, response.calls, response.reasoning, undefined, response.messageId, undefined, response.textOutputIndex, response.redacted);
		pending = [];
		finalText = response.text;
		if (!response.calls.length) { naturalStop = true; break; }
		for (const call of response.calls) {
			if (evalCount >= LIMITS.evals) break;
			evalCount++;
			let outcome: EvalOutcome;
			if (call.name !== "Eval" || typeof call.input.code !== "string") {
				outcome = { ok: false, state, logs: [], error: { code: "INVALID_EVAL_CALL", message: "只有 Eval 工具，输入必须为 code 字符串" }, interfaceViolation: "invalid native tool call" };
			} else {
				try { outcome = await executeEval(state, call.input.code); }
				catch (error) { infrastructureError = `SANDBOX: ${String(error).slice(0, 1500)}`; break; }
			}
			const previous = state.trace.length;
			state = outcome.state;
			if (outcome.ok) lastValue = outcome.value;
			const grade = challenge.grade(state, lastValue);
			if (evalCount === 1) firstEvalPass = grade.pass;
			const feedback = { ok: outcome.ok, value: outcome.value, error: outcome.error, logs: outcome.logs };
			record.evals.push({ number: evalCount, feedback, trace: state.trace.slice(previous), interfaceViolation: outcome.interfaceViolation, gradeAfterEval: grade });
			pending.push(adapter.formatToolResult(call.toolUseId, JSON.stringify(feedback), !outcome.ok, undefined, call.name));
		}
		if (infrastructureError || evalCount >= LIMITS.evals) break;
	}
	const grade = challenge.grade(state, lastValue);
	return {
		model, requestedEffort: "low", channelType, challenge: challenge.file, challengeId,
		apiHash: hash(api), challengeHash: hash(prompt), fixtureHash: hash(JSON.stringify(challenge.makeState())),
		firstEvalPass, finalPass: !infrastructureError && grade.pass, reasons: grade.reasons,
		infrastructureError, naturalStop, evalCount, durationMs: Date.now() - started,
		helps: state.trace.filter((t) => t.op === "help").length,
		uncaughtScriptErrors: turns.flatMap((t) => t.evals).filter((e) => !e.feedback.ok).length,
		interfaceViolations: turns.flatMap((t) => t.evals).filter((e) => e.interfaceViolation).length,
		finalText, lastValue, finalState: state, turns,
	};
}

async function runModels() {
	const api = await Bun.file(`${docs}/API.md`).text();
	const runId = new Date().toISOString().replace(/[:.]/g, "-");
	const files: string[] = [];
	const selectedCase = process.argv.find((a) => a.startsWith("--case="))?.slice(7);
	const selectedModel = process.argv.find((a) => a.startsWith("--model="))?.slice(8);
	const targetCases = selectedCase ? challenges.filter((c) => c.id === selectedCase) : challenges;
	const targets = selectedModel ? MODELS.filter((m) => m === selectedModel) : MODELS;
	if (!targets.length || !targetCases.length) throw new Error("Unknown model/case selection");
	await Promise.all(targets.map(async (model) => {
		for (const challenge of targetCases) {
			console.log(`START ${model} case=${challenge.id} effort=low`);
			const result = await runEpisode(model, challenge.id, api);
			const file = `${docs}/results/${runId}-${model.startsWith("nugjp") ? "luna" : "flash"}-${challenge.id}.json`;
			await Bun.write(file, `${JSON.stringify({ runId, limits: LIMITS, image: IMAGE, ...result }, null, 2)}\n`);
			files.push(file);
			console.log(JSON.stringify({ model, case: challenge.id, first: result.firstEvalPass, final: result.finalPass, evals: result.evalCount, helps: result.helps, infrastructureError: result.infrastructureError, reasons: result.reasons }));
			if (result.infrastructureError) break; // Diagnose infrastructure before spending on more calls.
		}
	}));
	await Bun.write(`${docs}/results/${runId}-manifest.json`, `${JSON.stringify({ runId, limits: LIMITS, models: targets, effort: "low", files, simulatorHash: hash(await Bun.file(`${root}scripts/task-call-challenges/runner.ts`).text()), graderHash: hash(await Bun.file(`${root}scripts/task-call-challenges/fixtures.ts`).text()) }, null, 2)}\n`);
	console.log(`RESULT_MANIFEST ${docs}/results/${runId}-manifest.json`);
}

try {
	if (process.argv.includes("--self-test")) await selfTest();
	else await runModels();
} catch (error) {
	console.error(safeError(error));
	process.exitCode = 1;
}

